events:
{% for event in events %}


    {{event.id}}
    {% unless event.status == 'live' %}{{ site.snippets.event_status[event.status] }}: {% endunless %} {{ event.name }}
    {{event.url | escape }}
    {{ event.starts_at | date: "%l:%M %p" | downcase | strip }}
    {{event.starts_at | date: "%d"}}
    {{ event.starts_at | date: "%b" }}
    {{ event.starts_at | date: "%a" }}
    {{ event.description_text | unescape | escape }}
    {{ event.place.visible_name }}{% if event.room_number %} {{ event.room_number }}{% endif %}

    {{ event.photo.card | escape | default: event.photo.huge }}

    {{ event.ticket_url | escape }}

     {% for department in event.departments %}
       {{ department.name | strip }}
     {% endfor %}


{% endfor %}
